    37  function TroubleshootPage() {
    38      const {translate} = useLocalize();
    39      const styles = useThemeStyles();
    40      const {isProduction} = useEnvironment();
    41      const [isConfirmationModalVisible, setIsConfirmationModalVisible] = useState(false);
    42      const waitForNavigate = useWaitForNavigation();
    43      const {shouldUseNarrowLayout} = useResponsiveLayout();
    44      const illustrationStyle = getLightbulbIllustrationStyle();
    45
    46      const menuItems = useMemo(() => {
    47          const debugConsoleItem: BaseMenuItem = {
    48              translationKey: 'initialSettingsPage.troubleshoot.viewConsole',
    49              icon: Expensicons.Bug,
    50              action: waitForNavigate(() => Navigation.navigate(ROUTES.SETTINGS_CONSOLE.getRoute(ROUTES.SETTINGS_TROUBLESHOOT))),
    51          };
    52
    53          const baseMenuItems: BaseMenuItem[] = [
    54              {
    55                  translationKey: 'initialSettingsPage.troubleshoot.clearCacheAndRestart',
    56                  icon: Expensicons.RotateLeft,
    57                  action: () => setIsConfirmationModalVisible(true),
    58              },
    59          ];
    60
    61
    62          return baseMenuItems
    63              .map((item) => ({
    64                  key: item.translationKey,
    65                  title: translate(item.translationKey),
    66                  icon: item.icon,
    67                  onPress: item.action,
    68                  wrapperStyle: [styles.sectionMenuItemTopDescription],
    69              }))
    70              .reverse();
    71      }, [translate, waitForNavigate, styles.sectionMenuItemTopDescription]);
    72
    73      return (
    74          <ScreenWrapper
    75              shouldEnablePickerAvoiding={false}
    76              shouldShowOfflineIndicatorInWideScreen
    77              testID={TroubleshootPage.displayName}
    78          >
    79              <HeaderWithBackButton
    80                  title={translate('initialSettingsPage.aboutPage.troubleshoot')}
    81                  shouldShowBackButton={shouldUseNarrowLayout}
    82                  shouldDisplaySearchRouter
    83                  onBackButtonPress={() => Navigation.goBack(ROUTES.SETTINGS)}
    84                  icon={Illustrations.Lightbulb}
    85              />
    86              <ScrollView contentContainerStyle={styles.pt3}>
    87                  <View style={[styles.flex1, shouldUseNarrowLayout ? styles.workspaceSectionMobile : styles.workspaceSection]}>
    88                      <Section
    89                          title={translate('initialSettingsPage.aboutPage.troubleshoot')}
    90                          subtitle={translate('initialSettingsPage.troubleshoot.description')}
    91                          isCentralPane
    92                          subtitleMuted
    93                          illustration={LottieAnimations.Desk}
    94                          illustrationStyle={illustrationStyle}
    95                          titleStyles={styles.accountSettingsSectionTitle}
    96                          renderSubtitle={() => (
    97                              <Text style={[styles.flexRow, styles.alignItemsCenter, styles.w100, styles.mt2]}>
    98                                  <Text style={[styles.textNormal, styles.colorMuted]}>{translate('initialSettingsPage.troubleshoot.description')}</Text>{' '}
    99                                  <TextLink
   100                                      style={styles.link}
   101                                      onPress={() => Report.navigateToConciergeChat()}
   102                                  >
   103                                      {translate('initialSettingsPage.troubleshoot.submitBug')}
   104                                  </TextLink>
   105                                  .
   106                              </Text>
   107                          )}
   108                      >
   109                          <View style={[styles.flex1, styles.mt5]}>
   110                              <View>
   111                                  <ClientSideLoggingToolMenu />
   112                              </View>
   113                              <MenuItemList
   114                                  menuItems={menuItems}
   115                                  shouldUseSingleExecution
   116                              />
   117                              <ConfirmModal
   118                                  title={translate('common.areYouSure')}
   119                                  isVisible={isConfirmationModalVisible}
   120                                  onConfirm={() => {
   121                                      setIsConfirmationModalVisible(false);
   122                                      // Requests in a sequential queue should be called even if the Onyx state is reset, so we do not lose any pending data.
   123                                      // However, the OpenApp request must be called before any other request in a queue to ensure data consistency.
   124                                      // To do that, sequential queue is cleared together with other keys, and then it's restored once the OpenApp request is resolved.
   125                                      const sequentialQueue = PersistedRequests.getAll();
   126                                      Onyx.clear(App.KEYS_TO_PRESERVE).then(() => {
   127                                          App.openApp().then(() => {
   128                                              if (!sequentialQueue) {
   129                                                  return;
   130                                              }
   131
   132                                              sequentialQueue.forEach((request) => {
   133                                                  PersistedRequests.save(request);
   134                                              });
   135                                          });
   136                                      });
   137                                  }}
   138                                  onCancel={() => setIsConfirmationModalVisible(false)}
   139                                  prompt={translate('initialSettingsPage.troubleshoot.confirmResetDescription')}
   140                                  confirmText={translate('initialSettingsPage.troubleshoot.resetAndRefresh')}
   141                                  cancelText={translate('common.cancel')}
   142                              />
   143                          </View>
   144                      </Section>
   145                  </View>
   146              </ScrollView>
   147          </ScreenWrapper>
   148      );
   149  }
   150
   151  TroubleshootPage.displayName = 'TroubleshootPage';
   152
   153  export default TroubleshootPage;

